const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define points for the two locations.
  const dallasport = ee.Geometry.Point([-120.91, 45.71]).buffer(5000); // Buffer to create a "region"
  const medford = ee.Geometry.Point([-122.87, 42.32]).buffer(5000); // Buffer to create a "region"

  // Date range covering the historic Pacific Northwest heatwave of late June 2021.
  const startDate = '2021-06-20';
  const endDate = '2021-07-10';

  // 2. Data Acquisition & Pre-processing
  // Use MODIS daily Land Surface Temperature data.
  const modisLST = ee.ImageCollection('MODIS/11A1/MCD11A1')
    .filterDate(startDate, endDate)
    .select('LST_Day_1km', 'QC_Day');

  // Check if the collection is empty
  if (modisLST.size().getInfo() === 0) {
    console.log(`No MODIS images found for the period ${startDate} to ${endDate}.`);
    console.log("A: No"); // It is known that MODIS data exists for this period, so this will evaluate as No, not C1.
    return;
  }

  // Function to convert LST from scaled Kelvin to Fahrenheit.
  // Formula: F = (K * 0.02 - 273.15) * 9/5 + 32
  const toFahrenheit = function(image) {
    const lstF = image.select('LST_Day_1km')
      .multiply(0.02)
      .subtract(273.15)
      .multiply(9.0 / 5.0)
      .add(32.0)
      .rename('LST_F');
    // Keep QA band for masking
    return image.addBands(lstF).select(['LST_F', 'QC_Day']);
  };

  // Function to mask pixels based on the QC_Day band. We want only the best quality pixels (bits 0-1 are 00).
  const maskQuality = function(image) {
    const qc = image.select('QC_Day');
    // Bits 0-1 are mandatory QA flags. 00 = LST produced, good quality.
    const qualityMask = qc.bitwiseAnd(0x03).eq(0);
    return image.updateMask(qualityMask);
  };

  const lstFahrenheit = modisLST.map(toFahrenheit).map(maskQuality).select('LST_F');

  // 3. Calculation
  // Find the maximum temperature for each location during the period.
  const maxTempImage = lstFahrenheit.max();

  const getStats = function(geometry, name) {
    const regionReducer = {
      reducer: ee.Reducer.max().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: geometry,
      scale: 1000, // MODIS LST is 1km
      maxPixels: 1e9
    };

    const stats = maxTempImage.reduceRegion(regionReducer);
    const maxVal = stats.get('LST_F_max');
    const count = stats.get('LST_F_count');

    // Handle potential nulls if no valid pixels are found
    if (maxVal.getInfo() === null || count.getInfo() === 0) {
        console.log(`${name}: No valid pixels found after quality masking.`);
        return { name: name, max: null, count: 0 };
    }
    return { name: name, max: maxVal.getInfo(), count: count.getInfo() };
  };

  const dallasportStats = getStats(dallasport, 'Dallasport');
  const medfordStats = getStats(medford, 'Medford');

  // 4. Validation & Final Answer
  if (dallasportStats.max === null || medfordStats.max === null) {
      console.log('C2');
      return;
  }

  console.log(`Dallasport Max Temp (F): ${dallasportStats.max.toFixed(2)}, Valid Pixels: ${dallasportStats.count}`);
  console.log(`Medford Max Temp (F): ${medfordStats.max.toFixed(2)}, Valid Pixels: ${medfordStats.count}`);

  // Check if either location exceeded the 105 F threshold.
  const dallasportHot = dallasportStats.max > 105;
  const medfordHot = medfordStats.max > 105;

  if (dallasportHot || medfordHot) {
    console.log("A: Yes");
  } else {
    console.log("B: No");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
  console.error(err);
  console.log("D");
});
